INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P051-01','CN0031','稀贵金属催化材料生产再利用产业化二阶段','2026-11验收转载；原件待核','2026-11-27','二阶段回收1210t/a及催化剂生产1100t/a，累计1950及1600分别记','转载含盐含重金属预处理及双效蒸发、水解/UASB/接触氧化，但原文设计/实际列未能核清，暂不确认投运','S051-01');
INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P051-02','CN0304','稀贵金属资源循环利用','建设收尾；预计2026-12试生产','2026-11-24','达产预计铂族金属25t/a','生产采用火法及湿法，废水专属工艺未取','S051-03');
INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P051-03','CN0119','10万吨特种化学品','2023募投规划；实际投产待核','2023','非催化剂专线；历史规划','共享污水站计划改造，设计项目排水40467m³/a','S025-01');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N051-01','CN0098','turn127831search84','验收监测与后评价源强','表3.1.5-3、3.1.5-4（正文称3.5.1-4）105–107页','四组点位两日各四次；逐项录入pH/COD/氨氮/SS或TDS及ND金属。原表效率铝系COD85% SS99%，铜系COD50%、氨氮99.5%、TDS92%。后评价源强及设备实际处理量与历史验收分开；蒸氨7t/h、报告时点3.5t/h，三效4t/h、1.7t/h；树脂60/37.6t/d，消解320/278t/d。铈/铝/铅名称异文保留；报告时点总排口纳南通能达。截图超时。','WEB_PRIMARY','公开网页正文/检索摘录；华茂截图已核','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N051-02','CN0119','S025-01','全公司历史环保费用','招股申报稿87页截图','2020/2021/2022环保费用49.40/136.25/169.15万元；环保设施支出909.00/803.81/24.11万元，合计958.40/940.06/193.26万元；危废处置费用0.51/0.37/0.92万元，量1.05/0.58/1.49t，单位0.48/0.63/0.62万元/t。全公司混合环保口径，不填污水OPEX表、不分配到催化剂。','WEB_COMPANY','公开网页正文/检索摘录；华茂截图已核','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N051-03','CN0119','S025-01','共享环保扩建规划','招股申报稿258页截图','10万吨特种化学品项目拟共享站膜处理与电催化改造，40467m³/a设计排水；3150万元是整体环保投资，不是废水专款。2023–2025计划不证建成。','WEB_COMPANY','公开网页正文/检索摘录；华茂截图已核','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N051-04','CN0031','S051-01','二阶段验收转载','2026-11-27检索摘录；原页受限','同题项目上市披露匹配铜川凯立。第一阶段回收740t/a、炭载金500t/a；第二阶段1210t/a及1100t/a，累计1950与1600。废水摘录含沉淀、双效蒸发、均质水解/UASB/接触氧化；废盐鉴别前危废管理。无法核清设计/实际对照列，保留证据而不建事实运行图。','WEB_SECONDARY','公开网页正文/检索摘录；华茂截图已核','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N051-05','CN0304','S051-03','建设进度','2026-11-24通海政府报道','等离子火法富集及多级湿法萃取；设备已安装、储罐区土建收尾。预计2026年12月底试生产、2027投产，25t/a铂族金属达产预计；99.5%以上为报道目标，不作实测。全系统密闭循环生产不等于废水零排。','WEB_PRIMARY','公开网页正文/检索摘录；华茂截图已核','2026-11-28');
