-- 051 second batch: historic measured water quality, newly identified recovery site, new phase evidence
PRAGMA foreign_keys=ON;
BEGIN;
UPDATE capacity SET product='综合催化剂及载体',basis='官网自述年产能',period='2026查阅',source_id='W01S03',notes='2023投产自述；含载体，非催化剂净产能或实产' WHERE capacity_id='C0031';
DELETE FROM capacity WHERE capacity_id='C050-04';
UPDATE evidence_notes SET source_id='W01S03' WHERE source_id='S050-06';
UPDATE search_log SET source_id='W01S03' WHERE source_id='S050-06';
DELETE FROM site_sources WHERE source_id='S050-06';
DELETE FROM sources WHERE source_id='S050-06';
UPDATE wastewater SET confidence='WEB_PRIMARY',flow_basis='后评价报告蒸氨塔+三效蒸发后源强；非蒸发进水',destination='厂区总排口至南通能达（报告时点）',notes='表3.1.5-3；不当成现行实测' WHERE water_id='W0029';
UPDATE sites SET water_summary=water_summary||'；2019验收历史监测补齐，2024环评列蒸氨7t/h（3.5实际）、三效4t/h（1.7实际）',as_of='2026-11-28' WHERE site_id='CN0098';
UPDATE sites SET capacity_summary=capacity_summary||'；2026二阶段验收转载累计回收1950t/a、催化剂生产1600t/a（非实产，非原3000设计叠加）',as_of='2026-11-28' WHERE site_id='CN0031';
COMMIT;
